SELECT JSON_OBJECT() FROM dual;
SELECT JSON_OBJECT(e.*) FROM employees e;
SELECT JSON_OBJECT('a' : 1 NULL ON NULL RETURNING VARCHAR(100 BYTE) WITH TYPENAME STRICT WITH UNIQUE KEYS) FROM dual;
SELECT JSON_OBJECT('a' VALUE NULL ABSENT ON NULL RETURNING VARCHAR(100 CHAR)) FROM dual;
SELECT JSON_OBJECT('a' VALUE 1 RETURNING VARCHAR(100)) FROM dual;
SELECT JSON_OBJECT('a' VALUE 1 RETURNING VARCHAR) FROM dual;
SELECT JSON_OBJECT('a' VALUE 1 RETURNING CLOB) FROM dual;
SELECT JSON_OBJECT('a' VALUE 1 RETURNING BLOB) FROM dual;
SELECT JSON_OBJECT('a' VALUE 1 RETURNING CLOB result_type) FROM dual;
SELECT JSON_OBJECT('a' VALUE 1 RETURNING JSON STRICT WITH UNIQUE KEYS) FROM dual;
